package com.customplugins.droprates;

/** All-defaults DropRatesConfig for the offline screenshot harness. */
class FakeDropRatesConfig implements DropRatesConfig
{
}

package com.customplugins.droprates;

import java.util.HashMap;
import java.util.Map;

/** In-memory ConfigStore for the offline screenshot harness. */
class FakeConfigStore implements ConfigStore
{
	private final Map<String, String> values = new HashMap<>();

	@Override
	public String get(String key)
	{
		return values.get(key);
	}

	@Override
	public void set(String key, String value)
	{
		values.put(key, value);
	}

	@Override
	public void unset(String key)
	{
		values.remove(key);
	}
}

package com.customplugins.droprates;

import com.google.gson.Gson;
import java.awt.Color;
import java.awt.Component;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.PluginPanel;

/**
 * Exercises the DropRatesConfig options (merge, sort modes, hidden categories/bosses,
 * collection tracking, custom fonts/colors) against fixed scenarios, without needing to
 * click through the real client. Not part of the shipped plugin.
 */
public class ConfigVariantsHarness
{
	public static void main(String[] args) throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				render();
			}
			catch (IOException e)
			{
				e.printStackTrace();
			}
		});
		System.exit(0);
	}

	private static void render() throws IOException
	{
		File outDir = new File("screenshots-config");
		outDir.mkdirs();
		for (File f : outDir.listFiles())
		{
			f.delete();
		}

		capture(outDir, "expanded-by-default", new FakeDropRatesConfig()
		{
			@Override
			public boolean collapseCategoriesByDefault()
			{
				return false;
			}
		}, new FakeConfigStore(), null);

		capture(outDir, "merged-alphabetical", new FakeDropRatesConfig()
		{
			@Override
			public boolean mergeAllCategories()
			{
				return true;
			}

			@Override
			public SortMode sortMode()
			{
				return SortMode.ALPHABETICAL;
			}

			@Override
			public boolean collapseCategoriesByDefault()
			{
				return false;
			}
		}, new FakeConfigStore(), null);

		capture(outDir, "combat-level-sort-wilderness", new FakeDropRatesConfig()
		{
			@Override
			public SortMode sortMode()
			{
				return SortMode.COMBAT_LEVEL;
			}

			@Override
			public boolean collapseCategoriesByDefault()
			{
				return false;
			}

			@Override
			public String categoryOrder()
			{
				return "Wilderness Bosses,Revenants";
			}
		}, new FakeConfigStore(), null);

		capture(outDir, "hidden-categories-and-bosses", new FakeDropRatesConfig()
		{
			@Override
			public String hiddenCategories()
			{
				return "Superior Creatures, Revenants";
			}

			@Override
			public String hiddenBosses()
			{
				return "Nex, Zulrah";
			}

			@Override
			public boolean collapseCategoriesByDefault()
			{
				return false;
			}
		}, new FakeConfigStore(), null);

		capture(outDir, "custom-fonts-and-colors", new FakeDropRatesConfig()
		{
			@Override
			public FontChoice fontChoice()
			{
				return FontChoice.MONOSPACED;
			}

			@Override
			public Color accentColor()
			{
				return new Color(0x4A, 0x90, 0xD9);
			}

			@Override
			public Color itemNameColor()
			{
				return new Color(0xE0, 0xC0, 0x80);
			}

			@Override
			public Color rateColor()
			{
				return new Color(0xFF, 0x80, 0x80);
			}

			@Override
			public boolean colorCodeSharedRates()
			{
				return false;
			}
		}, new FakeConfigStore(), "general-graardor");

		FakeConfigStore preCollected = new FakeConfigStore();
		preCollected.set("collected_general-graardor_bandos_hilt", "true");
		capture(outDir, "collection-tracking", new FakeDropRatesConfig()
		{
			@Override
			public boolean enableCollectionTracking()
			{
				return true;
			}
		}, preCollected, "general-graardor");
	}

	private static void capture(File outDir, String name, DropRatesConfig config, ConfigStore configStore, String bossId) throws IOException
	{
		Gson gson = new Gson();
		DropDataService service = new DropDataService(gson);
		DropRatesPanel panel = new DropRatesPanel(service, config, configStore);

		JFrame frame = new JFrame();
		frame.setUndecorated(true);
		frame.setLocation(-3000, -3000);
		frame.add(panel);
		frame.setSize(PluginPanel.PANEL_WIDTH + 20, 2400);
		frame.setVisible(true);
		frame.validate();

		if (bossId != null)
		{
			BossData data = service.getAll().stream().filter(b -> b.getId().equals(bossId)).findFirst().orElseThrow();
			panel.showEntry(data);
			frame.validate();
		}

		BufferedImage img = capture(panel);
		ImageIO.write(img, "png", new File(outDir, name + ".png"));

		frame.dispose();
	}

	private static BufferedImage capture(Component component) throws IOException
	{
		int width = component.getWidth();
		int height = Math.max(component.getHeight(), 1);
		BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		component.paint(img.getGraphics());
		return img;
	}
}

package com.customplugins.droprates;

import com.google.gson.Gson;
import java.awt.Component;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.PluginPanel;

/**
 * Renders the plugin's panel to PNG files without launching the game client,
 * for fast visual iteration during development. Not part of the shipped plugin.
 */
public class ScreenshotHarness
{
	public static void main(String[] args) throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				render();
			}
			catch (IOException e)
			{
				e.printStackTrace();
			}
		});
		System.exit(0);
	}

	private static void render() throws IOException
	{
		Gson gson = new Gson();
		DropDataService service = new DropDataService(gson);
		DropRatesPanel panel = new DropRatesPanel(service, new FakeDropRatesConfig(), new FakeConfigStore());

		JFrame frame = new JFrame();
		frame.setUndecorated(true);
		frame.setLocation(-3000, -3000);
		frame.add(panel);
		frame.setSize(PluginPanel.PANEL_WIDTH + 20, 2400);
		frame.setVisible(true);
		frame.validate();

		File outDir = new File("screenshots");
		outDir.mkdirs();
		for (File f : outDir.listFiles())
		{
			f.delete();
		}

		capture(panel, new File(outDir, "00-list.png"));

		panel.searchForTesting("shard");
		frame.validate();
		capture(panel, new File(outDir, "00-search-shard.png"));
		panel.searchForTesting("");

		for (BossData data : service.getAll())
		{
			panel.showEntry(data);
			frame.validate();
			capture(panel, new File(outDir, data.getId() + ".png"));
		}

		frame.dispose();
	}

	private static void capture(Component component, File file) throws IOException
	{
		int width = component.getWidth();
		int height = Math.max(component.getHeight(), 1);
		BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		component.paint(img.getGraphics());
		ImageIO.write(img, "png", file);
	}
}

package com.customplugins.droprates;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
class DropDataService
{
	private final List<BossData> entries = new ArrayList<>();
	private final Map<String, BossData> byNpcName = new HashMap<>();

	@Inject
	DropDataService(Gson gson)
	{
		try (InputStream is = getClass().getResourceAsStream("drop-data.json"))
		{
			if (is == null)
			{
				log.warn("drop-data.json not found on classpath");
			}
			else
			{
				DropDataRoot root = gson.fromJson(new InputStreamReader(is, StandardCharsets.UTF_8), DropDataRoot.class);
				if (root != null && root.getEntries() != null)
				{
					entries.addAll(root.getEntries());
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to load drop-data.json", e);
		}

		for (BossData entry : entries)
		{
			if (entry.getNpcNames() == null)
			{
				continue;
			}

			for (String npcName : entry.getNpcNames())
			{
				byNpcName.put(npcName.toLowerCase(), entry);
			}
		}
	}

	List<BossData> getAll()
	{
		return Collections.unmodifiableList(entries);
	}

	BossData findByNpcName(String npcName)
	{
		if (npcName == null)
		{
			return null;
		}

		return byNpcName.get(npcName.toLowerCase());
	}

	/**
	 * Matches by boss name OR by any item name the boss can drop (main drops,
	 * drop groups, pet, secondary sources, CoX-style weighted uniques), so
	 * searching "shard" finds every boss with a shard drop.
	 */
	List<BossData> search(String query)
	{
		String lower = query.toLowerCase().trim();
		if (lower.isEmpty())
		{
			return getAll();
		}

		List<BossData> results = new ArrayList<>();
		for (BossData entry : entries)
		{
			if (entry.getDisplayName().toLowerCase().contains(lower) || matchesItemName(entry, lower))
			{
				results.add(entry);
			}
		}

		return results;
	}

	private static boolean matchesItemName(BossData entry, String lower)
	{
		if (containsMatch(entry.getDrops(), Drop::getItem, lower))
		{
			return true;
		}

		if (entry.getDropGroups() != null)
		{
			for (DropGroup group : entry.getDropGroups())
			{
				if (containsMatch(group.getDrops(), Drop::getItem, lower))
				{
					return true;
				}
			}
		}

		if (entry.getPet() != null && entry.getPet().getItem().toLowerCase().contains(lower))
		{
			return true;
		}

		if (entry.getSecondarySources() != null)
		{
			for (SecondarySource source : entry.getSecondarySources())
			{
				if (containsMatch(source.getDrops(), Drop::getItem, lower))
				{
					return true;
				}
			}
		}

		if (containsMatch(entry.getUniqueItems(), WeightedItem::getItem, lower))
		{
			return true;
		}

		if (containsMatch(entry.getUniqueItemsChallengeMode(), WeightedItem::getItem, lower))
		{
			return true;
		}

		if (entry.getBrotherItems() != null)
		{
			for (BrotherItems brother : entry.getBrotherItems())
			{
				for (String item : brother.getItems())
				{
					if (item.toLowerCase().contains(lower))
					{
						return true;
					}
				}
			}
		}

		return false;
	}

	private static <T> boolean containsMatch(List<T> list, java.util.function.Function<T, String> nameExtractor, String lower)
	{
		if (list == null)
		{
			return false;
		}

		for (T item : list)
		{
			if (nameExtractor.apply(item).toLowerCase().contains(lower))
			{
				return true;
			}
		}

		return false;
	}
}

package com.customplugins.droprates;

import java.util.List;
import lombok.Getter;

@Getter
class BossData
{
	private String id;
	private String displayName;
	private String category;
	private Integer combatLevel;
	private List<String> npcNames;
	private DropEntryType type;

	// MULTI_ROLL
	private Integer rollsPerKill;

	// SIMPLE / MULTI_ROLL
	private List<Drop> drops;
	private List<CombinedRate> combined;

	// SIMPLE / MULTI_ROLL - use instead of drops/combined when a monster has more
	// than one mechanically-separate table (e.g. Zulrah's uniques vs. mutagens)
	private List<DropGroup> dropGroups;

	// SIMPLE / MULTI_ROLL - a pet is often a separate roll with its own rules
	private Drop pet;

	// SIMPLE - other monsters that can drop the same uniques at a different rate
	private List<SecondarySource> secondarySources;

	// KILLCOUNT_FORMULA - killcountRates holds the PER-ROLL denominator for each count;
	// rolls(count) = baseRolls + extraRollsPerCount * count, and the effective
	// "any unique" / "specific item" chances are computed from that, not stored directly
	private String formulaLabel;
	private List<KillcountRate> killcountRates;
	private Integer baseRolls;
	private Integer extraRollsPerCount;
	private Integer itemsPerCount;
	private List<BrotherItems> brotherItems;

	// POINTS_BASED
	private Integer pointsPerPercent;
	private Double capPercent;
	private Integer capPoints;
	private Integer maxUniques;
	private List<WeightedItem> uniqueItems;
	private Integer uniqueItemsWeightTotal;
	private List<WeightedItem> uniqueItemsChallengeMode;
	private Integer uniqueItemsChallengeModeWeightTotal;

}

package com.customplugins.droprates;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "Unique Drop Rates",
	description = "Look up a monster's unique drop rates (individual and combined odds) before you go fight it",
	tags = {"drops", "rates", "uniques", "wiki", "loot"}
)
public class DropRatesPlugin extends Plugin
{
	private static final String MENU_OPTION = "View drop rates";
	private static final String CONFIG_GROUP = "droprates";

	@Inject
	private Client client;

	@Inject
	private DropDataService dropDataService;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private DropRatesConfig config;

	@Inject
	private ConfigManager configManager;

	private final Set<Integer> handledThisTick = new HashSet<>();

	private DropRatesPanel panel;
	private NavigationButton navButton;

	@Provides
	DropRatesConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DropRatesConfig.class);
	}

	@Override
	protected void startUp()
	{
		ConfigStore configStore = new ConfigStore()
		{
			@Override
			public String get(String key)
			{
				return configManager.getConfiguration(CONFIG_GROUP, key);
			}

			@Override
			public void set(String key, String value)
			{
				configManager.setConfiguration(CONFIG_GROUP, key, value);
			}

			@Override
			public void unset(String key)
			{
				configManager.unsetConfiguration(CONFIG_GROUP, key);
			}
		};

		panel = new DropRatesPanel(dropDataService, config, configStore);

		navButton = NavigationButton.builder()
			.tooltip("Unique Drop Rates")
			.icon(createIcon())
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(CONFIG_GROUP))
		{
			panel.onConfigChanged();
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		handledThisTick.clear();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		NPC npc = event.getMenuEntry().getNpc();
		if (npc == null || npc.getName() == null || npc.getCombatLevel() <= 0)
		{
			return;
		}

		if (!handledThisTick.add(npc.getIndex()))
		{
			return;
		}

		BossData data = dropDataService.findByNpcName(npc.getName());
		if (data == null)
		{
			return;
		}

		client.getMenu().createMenuEntry(-1)
			.setOption(MENU_OPTION)
			.setTarget(event.getMenuEntry().getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(e -> openEntry(data));
	}

	private void openEntry(BossData data)
	{
		clientToolbar.openPanel(navButton);
		panel.showEntry(data);
	}

	private static BufferedImage createIcon()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(220, 138, 0));
		g.fillOval(0, 0, 16, 16);
		g.setColor(Color.WHITE);
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 11));
		g.drawString("%", 3, 12);
		g.dispose();
		return icon;
	}
}

package com.customplugins.droprates;

import java.util.List;
import lombok.Getter;

/**
 * A distinct sub-table within one monster's drops (e.g. Zulrah's main uniques
 * vs. its separate mutagen sub-table) - kept apart so combined odds aren't
 * miscalculated across mechanically unrelated tables.
 */
@Getter
class DropGroup
{
	private String groupName;
	private List<Drop> drops;
	private List<CombinedRate> combined;
}

package com.customplugins.droprates;

import lombok.Getter;

@Getter
class WeightedItem
{
	private String item;
	private int weight;
}

package com.customplugins.droprates;

import java.util.List;
import lombok.Getter;

@Getter
class BrotherItems
{
	private String brother;
	private List<String> items;
}

package com.customplugins.droprates;

import lombok.Getter;

@Getter
class KillcountRate
{
	private int count;
	private int denominator;
}

package com.customplugins.droprates;

import java.util.List;
import lombok.Getter;

/**
 * A different monster that can drop the same uniques as a boss, but at a
 * different rate (e.g. GWD bodyguards dropping the boss's own armour pieces).
 */
@Getter
class SecondarySource
{
	private String sourceName;
	private List<Drop> drops;
	private List<CombinedRate> combined;
}

package com.customplugins.droprates;

/**
 * The reward mechanism a dataset entry uses - these are structurally different
 * (a flat per-item rate table isn't accurate for a boss whose odds depend on
 * killcount, team points, etc.) so each type gets its own rendering in the panel.
 */
enum DropEntryType
{
	/** A flat list of item:rate pairs, optionally with precomputed combined odds. */
	SIMPLE,
	/** Same as SIMPLE, but the table is rolled more than once per kill (e.g. Zulrah, Grotesque Guardians). */
	MULTI_ROLL,
	/** Odds depend on how many of a set of related NPCs were killed before looting (Barrows). */
	KILLCOUNT_FORMULA,
	/** Odds depend on total points earned across an activity, not a single kill (raids). */
	POINTS_BASED
}

package com.customplugins.droprates;

/**
 * Thin wrapper around persisted per-key string state (collapsed categories, collected items).
 * Exists so the offline screenshot harness can supply a trivial in-memory fake instead of
 * needing a real RuneLite ConfigManager.
 */
interface ConfigStore
{
	String get(String key);

	void set(String key, String value);

	void unset(String key);
}

package com.customplugins.droprates;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.ui.ColorScheme;

@ConfigGroup("droprates")
public interface DropRatesConfig extends Config
{
	String LAYOUT_SECTION = "layoutSection";
	String APPEARANCE_SECTION = "appearanceSection";
	String COLLECTION_SECTION = "collectionSection";

	@ConfigSection(
		name = "Layout & sorting",
		description = "Category order, sorting, and hiding entries",
		position = 0
	)
	String layoutSection = LAYOUT_SECTION;

	@ConfigSection(
		name = "Appearance",
		description = "Fonts and colors",
		position = 1,
		closedByDefault = true
	)
	String appearanceSection = APPEARANCE_SECTION;

	@ConfigSection(
		name = "Collection tracking",
		description = "Mark drops as already collected",
		position = 2,
		closedByDefault = true
	)
	String collectionSection = COLLECTION_SECTION;

	@ConfigItem(
		keyName = "collapseCategoriesByDefault",
		name = "Collapse categories by default",
		description = "Start with every category collapsed until you click to expand it",
		position = 0,
		section = LAYOUT_SECTION
	)
	default boolean collapseCategoriesByDefault()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sortMode",
		name = "Sort bosses by",
		description = "How bosses are ordered within each category (or the whole list, if merged)",
		position = 1,
		section = LAYOUT_SECTION
	)
	default SortMode sortMode()
	{
		return SortMode.DEFAULT;
	}

	@ConfigItem(
		keyName = "mergeAllCategories",
		name = "Merge all categories",
		description = "Show a single flat list instead of grouping by category",
		position = 2,
		section = LAYOUT_SECTION
	)
	default boolean mergeAllCategories()
	{
		return false;
	}

	@ConfigItem(
		keyName = "categoryOrder",
		name = "Category order override",
		description = "Comma-separated category names, in the order you want them shown. Unlisted categories keep the default order and are shown after these.",
		position = 3,
		section = LAYOUT_SECTION
	)
	default String categoryOrder()
	{
		return "";
	}

	@ConfigItem(
		keyName = "hiddenCategories",
		name = "Hidden categories",
		description = "Comma-separated category names to hide entirely",
		position = 4,
		section = LAYOUT_SECTION
	)
	default String hiddenCategories()
	{
		return "";
	}

	@ConfigItem(
		keyName = "hiddenBosses",
		name = "Hidden bosses",
		description = "Comma-separated boss names to hide entirely",
		position = 5,
		section = LAYOUT_SECTION
	)
	default String hiddenBosses()
	{
		return "";
	}

	@ConfigItem(
		keyName = "fontChoice",
		name = "Font",
		description = "Font used throughout the panel",
		position = 0,
		section = APPEARANCE_SECTION
